<?php
use App\Application\MarketData\Services\MarketDataEvidenceExportService;
use App\Infrastructure\Persistence\MarketData\EodEvidenceRepository;
use Illuminate\Support\Facades\DB;
use Tests\Support\UsesMarketDataSqlite;

/** Exact persisted source literals are inputs, never derived from exported output. */
class B19RunEvidenceTelemetryProofTest extends TestCase
{
    use UsesMarketDataSqlite;
    private $dirs=[];
    protected function setUp(): void {parent::setUp();$this->bootMarketDataSqlite();}
    protected function tearDown(): void {foreach($this->dirs as $d){foreach(glob($d.'/*') as $p)if(is_file($p))unlink($p);if(is_dir($d))rmdir($d);}$this->tearDownMarketDataSqlite();parent::tearDown();}
    private function runRow(array $v=[]): int {return DB::table('eod_runs')->insertGetId(array_merge(['trade_date_requested'=>'2026-04-21','trade_date_effective'=>null,'source'=>'api','terminal_status'=>'FAILED','publishability_state'=>'NOT_READABLE','coverage_gate_state'=>'NOT_EVALUABLE','coverage_reason_code'=>'RUN_COVERAGE_NOT_EVALUABLE','final_reason_code'=>'RUN_SOURCE_TIMEOUT','notes'=>'source_name=NOTE_ONLY; source_provider=own-provider','created_at'=>'2026-04-21 17:10:00','started_at'=>'2026-04-21 17:00:00','finished_at'=>'2026-04-21 17:10:00'],$v));}
    private function telemetry(): array {return ['source_mode'=>'api','source_name'=>'OWN_SOURCE','provider'=>'own-provider','timeout_seconds'=>17,'retry_max'=>4,'attempt_count'=>2,'success_after_retry'=>true,'final_http_status'=>201,'final_reason_code'=>'RUN_SOURCE_TIMEOUT','captured_at'=>'2026-04-21T17:01:00+07:00','attempts'=>[['attempt_number'=>1,'reason_code'=>'RUN_SOURCE_TIMEOUT','http_status'=>504,'throttle_delay_ms'=>101,'backoff_delay_ms'=>251,'will_retry'=>true],['attempt_number'=>2,'reason_code'=>null,'http_status'=>201,'throttle_delay_ms'=>102,'backoff_delay_ms'=>0,'will_retry'=>false]]];}
    private function event($run,array $source,$wrapper='source_acquisition',$time='2026-04-21 17:02:00',$stage='IMPORT'): int {return DB::table('eod_run_events')->insertGetId(['run_id'=>$run,'trade_date_requested'=>'2026-04-21','event_time'=>$time,'stage'=>$stage,'event_type'=>'STAGE_COMPLETED','severity'=>'WARN','reason_code'=>'RUN_SOURCE_TIMEOUT','message'=>'Independent source attempt fixture','event_payload_json'=>json_encode([$wrapper=>$source]),'created_at'=>$time]);}
    private function export($run): array {$dir=sys_get_temp_dir().'/b19_run_evidence_'.uniqid();$this->dirs[]=$dir;app(MarketDataEvidenceExportService::class)->exportRunEvidence($run,$dir);return [json_decode(file_get_contents($dir.'/evidence_pack.json'),true),$dir];}
    public static function telemetryRules(): array {$r=[];foreach(range(176,204) as $n)$r['R'.$n]=[$n];return $r;}
    /** @dataProvider telemetryRules */
    public function test_each_telemetry_member_has_its_own_persisted_value(int $id): void {
        $run=$this->runRow();$own=$this->telemetry();$event=$this->event($run,$own);$foreign=$this->runRow();$this->event($foreign,array_merge($own,['provider'=>'FOREIGN']),'source_acquisition','2026-04-21 23:00:00');
        $before=DB::table('eod_run_events')->orderBy('event_id')->get()->toJson();[$pack,$dir]=$this->export($run);$t=$pack['source_attempt_telemetry'];$this->assertSame($before,DB::table('eod_run_events')->orderBy('event_id')->get()->toJson());
        $top=[176=>['event_id',$event],177=>['event_time','2026-04-21 17:02:00'],178=>['event_type','STAGE_COMPLETED'],179=>['source_name','OWN_SOURCE'],180=>['provider','own-provider'],181=>['timeout_seconds',17],182=>['retry_max',4],183=>['attempt_count',2],184=>['success_after_retry','yes'],185=>['final_http_status',201],186=>['final_reason_code','RUN_SOURCE_TIMEOUT'],187=>['captured_at','2026-04-21T17:01:00+07:00']];
        if(isset($top[$id])){$this->assertSame($top[$id][1],$t[$top[$id][0]]);}
        elseif($id===188){$this->assertSame($own['attempts'],$t['attempts']);}
        elseif($id>=189&&$id<=200){$index=$id<195?0:1;$field=['attempt_number','reason_code','http_status','throttle_delay_ms','backoff_delay_ms','will_retry'][($id-189)%6];$this->assertSame($own['attempts'][$index][$field],$t['attempts'][$index][$field]);}
        elseif($id===201){$this->assertSame($event,$t['event_id']);$this->assertSame('own-provider',$t['provider']);$this->assertSame('IMPORT',DB::table('eod_run_events')->where('event_id',$t['event_id'])->value('stage'));}
        elseif($id===202){$this->assertFileExists($dir.'/source_attempt_telemetry.json');$empty=$this->runRow();[$p,$d]=$this->export($empty);$this->assertNull($p['source_attempt_telemetry']);$this->assertFileDoesNotExist($d.'/source_attempt_telemetry.json');}
        elseif($id===203){unset($own['source_name'],$own['provider']);$r=$this->runRow(['notes'=>'source_name=NOTE_ONLY; source_provider=note-provider']);$this->event($r,$own);[$p]=$this->export($r);$this->assertSame('NOTE_ONLY',$p['source_attempt_telemetry']['source_name']);$this->assertSame('note-provider',$p['source_attempt_telemetry']['provider']);$this->assertSame($own['attempts'],$p['source_attempt_telemetry']['attempts']);}
        else {$this->assertSame($event,$t['event_id']);$this->assertCount(2,$t['attempts']);$this->assertSame($before,DB::table('eod_run_events')->orderBy('event_id')->get()->toJson());}
    }
    public function test_summary_without_attempt_rows_does_not_materialize_attempt_companion(): void {$run=$this->runRow();$this->event($run,['source_name'=>'SUMMARY_ONLY','attempt_count'=>9,'final_reason_code'=>'RUN_SOURCE_TIMEOUT']);[$p,$d]=$this->export($run);$this->assertNull($p['source_attempt_telemetry']);$this->assertFileDoesNotExist($d.'/source_attempt_telemetry.json');$this->assertSame('ADMITTED_INCOMPLETE',$p['evidence_admission']['evidence_admission_state']);}
    public function test_own_import_event_wins_over_later_unrelated_stage_and_other_run(): void {$run=$this->runRow();$own=$this->telemetry();$id=$this->event($run,$own);$this->event($run,array_merge($own,['provider'=>'UNRELATED_FINALIZE']),'exception_context','2026-04-21 22:00:00','FINALIZE');$t=(new EodEvidenceRepository())->exportRunSourceAttemptTelemetry($run);$this->assertSame($id,$t['event_id']);$this->assertSame('own-provider',$t['provider']);}
    public function test_missing_capture_is_unavailable_not_replaced_with_event_time(): void {$r=$this->runRow();$s=$this->telemetry();unset($s['captured_at']);$this->event($r,$s);[$p]=$this->export($r);$this->assertNull($p['source_attempt_telemetry']['captured_at']);$this->assertSame('ADMITTED_INCOMPLETE',$p['evidence_admission']['evidence_admission_state']);$this->assertContains('source_attempt_telemetry.captured_at',$p['evidence_admission']['missing_sections']);}
    public function test_malformed_attempts_never_become_invented_rows_or_complete_evidence(): void {$r=$this->runRow();$s=$this->telemetry();$s['attempts']=[null,'bad-row'];$this->event($r,$s);[$p]=$this->export($r);$this->assertSame([],$p['source_attempt_telemetry']['attempts']);$this->assertArrayHasKey('telemetry_integrity',$p['source_attempt_telemetry']);$this->assertSame('UNAVAILABLE',$p['source_attempt_telemetry']['telemetry_integrity']['status']);$this->assertSame('ADMITTED_INCOMPLETE',$p['evidence_admission']['evidence_admission_state']);}
    public function test_explicit_no_is_not_truthy_yes_and_explicit_null_is_not_note_repair(): void {$r=$this->runRow(['notes'=>'source_success_after_retry=yes; source_final_reason_code=STALE_REASON']);$s=$this->telemetry();$s['success_after_retry']='no';$s['final_reason_code']=null;$this->event($r,$s);[$p]=$this->export($r);$this->assertSame('no',$p['source_attempt_telemetry']['success_after_retry']);$this->assertNull($p['source_attempt_telemetry']['final_reason_code']);}
    public function test_contradictory_payload_run_identity_cannot_be_verified(): void {$r=$this->runRow();$s=$this->telemetry();$s['run_id']=$r+1;$this->event($r,$s);[$p]=$this->export($r);$this->assertArrayHasKey('telemetry_integrity',$p['source_attempt_telemetry']);$this->assertSame('UNAVAILABLE',$p['source_attempt_telemetry']['telemetry_integrity']['status']);$this->assertSame('ADMITTED_INCOMPLETE',$p['evidence_admission']['evidence_admission_state']);}
    public function test_exception_import_payload_is_retained_but_malformed_values_unavailable(): void {$r=$this->runRow();$s=$this->telemetry();$s['timeout_seconds']='not-number';$s['attempts'][0]['will_retry']='false';$this->event($r,$s,'exception_context');[$p]=$this->export($r);$this->assertNull($p['source_attempt_telemetry']['timeout_seconds']);$this->assertNull($p['source_attempt_telemetry']['attempts'][0]['will_retry']);$this->assertArrayHasKey('telemetry_integrity',$p['source_attempt_telemetry']);$this->assertSame('UNAVAILABLE',$p['source_attempt_telemetry']['telemetry_integrity']['status']);}
    public static function anomalyRules(): array {$r=[];foreach([160,161,162,163,164,165,172,173] as $n)$r['R'.$n]=[$n];return $r;}
    /** @dataProvider anomalyRules */
    public function test_anomaly_narrative_keeps_run_facts_and_does_not_claim_unverified_safety(int $id): void {
        $r=$this->runRow(['trade_date_effective'=>'2026-04-20','terminal_status'=>'HELD','coverage_gate_state'=>'FAIL','coverage_reason_code'=>'RUN_COVERAGE_LOW']);$this->event($r,$this->telemetry());[$p,$d]=$this->export($r);$md=file_get_contents($d.'/anomaly_report.md');
        switch($id){case 160:$this->assertStringContainsString('- Run ID: '.$r,$md);break;case 161:$this->assertStringContainsString('- Requested date: 2026-04-21',$md);$this->assertStringContainsString('- Effective date: 2026-04-20',$md);break;case 162:$this->assertStringContainsString('RUN_SOURCE_TIMEOUT',$md);$this->assertSame('RUN_SOURCE_TIMEOUT',$p['dominant_reason_codes'][0]['reason_code']);break;case 163:$this->assertStringContainsString('- Status explanation: HELD; reason=RUN_SOURCE_TIMEOUT',$md);$this->assertStringContainsString('- Status: HELD',$md);$this->assertStringContainsString('RUN_SOURCE_TIMEOUT',$md);break;case 164:$this->assertStringContainsString('- Consumer effect: fallback effective date 2026-04-20; publication identity unverified',$md);$this->assertTrue($p['fallback_context']['fallback_used']);break;case 165:case 173:$this->assertStringNotContainsString('current sealed publication present',$md);$this->assertStringContainsString('not proven readable',$md);$this->assertNull($p['publication_manifest']);break;case 172:$this->assertStringContainsString($p['run_summary']['terminal_status'],$md);$this->assertStringContainsString($p['run_summary']['trade_date_requested'],$md);break;}
        $this->assertSame('ADMITTED_INCOMPLETE',$p['evidence_admission']['evidence_admission_state']);
    }
    public function test_latest_own_attempt_event_is_bounded_and_complete_trail_is_preserved(): void {
        $r=$this->runRow();$first=$this->telemetry();$this->event($r,$first);$last=$first;$last['provider']='last-provider';$id=$this->event($r,$last,'source_acquisition','2026-04-21 17:03:00');$before=DB::table('eod_run_events')->where('run_id',$r)->get()->toJson();[$p]=$this->export($r);$this->assertSame($id,$p['source_attempt_telemetry']['event_id']);$this->assertSame('last-provider',$p['source_attempt_telemetry']['provider']);$this->assertCount(2,$p['source_attempt_telemetry']['attempts']);$this->assertSame($before,DB::table('eod_run_events')->where('run_id',$r)->get()->toJson());$this->assertSame(2,$p['run_event_summary']['event_count']);
    }
    public static function malformedFields(): array {return [['final_http_status',999],['provider',['not-a-provider']],['captured_at','not-a-date'],['captured_at','2026-02-30 17:01:00'],['event_id',999999],['trade_date','2000-01-01']];}
    /** @dataProvider malformedFields */
    public function test_malformed_or_foreign_context_cannot_admit_complete_telemetry(string $field,$bad): void {
        $r=$this->runRow();$s=$this->telemetry();$s[$field]=$bad;$this->event($r,$s);[$p]=$this->export($r);$this->assertArrayHasKey('telemetry_integrity',$p['source_attempt_telemetry']);$this->assertSame('UNAVAILABLE',$p['source_attempt_telemetry']['telemetry_integrity']['status']);$this->assertSame('ADMITTED_INCOMPLETE',$p['evidence_admission']['evidence_admission_state']);
    }

    public function test_missing_total_attempt_count_is_not_invented_from_bounded_rows(): void {$r=$this->runRow();$s=$this->telemetry();unset($s['attempt_count']);$this->event($r,$s);[$p]=$this->export($r);$this->assertNull($p['source_attempt_telemetry']['attempt_count']);$this->assertSame('UNAVAILABLE',$p['source_attempt_telemetry']['telemetry_integrity']['status']);}
    public function test_missing_final_http_status_cannot_hide_a_contradictory_known_last_response(): void {$r=$this->runRow();$s=$this->telemetry();$s['final_http_status']=null;$this->event($r,$s);[$p]=$this->export($r);$this->assertNull($p['source_attempt_telemetry']['final_http_status']);$this->assertSame('UNAVAILABLE',$p['source_attempt_telemetry']['telemetry_integrity']['status']);}

}
